// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: setOwner succeeds if and only if the caller is the current owner.
        assertTrue(ok == (actor == c.owner()), "only the owner may change owner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        address before = c.owner();
        vm.prank(actor);
        try c.setOwner(newOwner) { /* succeeded */ } catch { /* reverted */ }
        // General rule: owner is unchanged unless the caller was already the owner.
        assertTrue(c.owner() == before || actor == before);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // Rule (universal): from the moment of deployment, whoever is the current owner
        // can always hand ownership to ANY fuzzed address in one call:
        // after the owner calls setOwner(newOwner), c.owner() == newOwner.
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        vm.assume(ok); // admissible runs are those where the call succeeds: exactly the owner in P
        assertTrue(c.owner() == newOwner);
    }
}
